from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 12))
    mode = draw(st.integers(0, 4))
    if mode == 0:
        s = "0" * n
    elif mode == 1:
        s = "1" * n
    elif mode == 2:
        s = "".join("01"[i % 2] for i in range(n))
    else:
        s = "".join(draw(st.lists(st.sampled_from("01"), min_size=n, max_size=n)))
    return f"{n}\n{s}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 2:
        return False
    try:
        n = int(t[0])
    except ValueError:
        return False
    s = t[1]
    if not (1 <= n <= 10**6):
        return False
    if len(s) != n:
        return False
    return all(c in "01" for c in s)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    s = t[1]
    total = 0
    for i in range(n):
        v = int(s[i])
        total += v  # f(i,i) = A_i
        for j in range(i + 1, n):
            # NAND: 0 nand 0 = 1, 0 nand 1 = 1, 1 nand 0 = 1, 1 nand 1 = 0
            v = 1 - (v & int(s[j]))
            total += v
    return str(total)
