from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.one_of(
        st.integers(1, 3),
        st.integers(1, 12),
    ))
    kind = draw(st.sampled_from(["random", "all0", "all1", "alt"]))
    if kind == "random":
        s = draw(st.text(alphabet="01", min_size=n, max_size=n))
    elif kind == "all0":
        s = "0" * n
    elif kind == "all1":
        s = "1" * n
    else:
        s = "".join("01"[i % 2] for i in range(n))
    return f"{n}\n{s}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 2:
        return False
    if not t[0].isdigit():
        return False
    n = int(t[0])
    s = t[1]
    if not (1 <= n <= 10**6):
        return False
    if len(s) != n:
        return False
    return all(c in "01" for c in s)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    s = t[1]
    a = [int(c) for c in s]

    def nand(x, y):
        return 0 if (x == 1 and y == 1) else 1

    total = 0
    for i in range(n):
        cur = a[i]
        total += cur
        for j in range(i + 1, n):
            cur = nand(cur, a[j])
            total += cur
    return str(total)
